import { expect, test } from "bun:test";

import { isToolFailureKind, toolFailureRate, toolFailureSummary } from "../src/tools.ts";

test("isToolFailureKind matches only the failed kind", () => {
  expect(isToolFailureKind("agent.tool_call.failed")).toBe(true);
  expect(isToolFailureKind("agent.tool_call")).toBe(false);
  expect(isToolFailureKind("agent.thought")).toBe(false);
});

test("toolFailureSummary counts attempts and failures", () => {
  expect(
    toolFailureSummary([
      { kind: "agent.tool_call", ts: "2026-06-11T09:00:10Z" },
      { kind: "agent.tool_call.failed", ts: "2026-06-11T09:01:00Z" },
    ]),
  ).toEqual({ attempts: 1, failures: 1, failure_ts: ["2026-06-11T09:01:00Z"] });
});

test("toolFailureRate is failures over all tool calls", () => {
  expect(toolFailureRate([{ kind: "agent.tool_call.failed" }])).toBe(1);
  expect(toolFailureRate([])).toBeNull();
});
